1	/**
2	 * Framework-neutral detection for the operator flows.
3	 *
4	 * This module reads an application tree and states what it found. It composes
5	 * the frozen adapters' own published readings — the Angular target cell's
6	 * ecosystem registry is the only per-package verdict surface either lineage
7	 * publishes — and it never fills a gap with a plausible value: a package the
8	 * cell has no reading for is reported `unknown`, a runtime the tree does not
9	 * declare is reported `unknown`, and a lineage that publishes no cell registry
10	 * is reported as having none rather than as having an empty one.
11	 *
12	 * Nothing here decides *what to change*. That lives in the frozen adapters.
13	 */
14	
15	import { readdir, readFile, stat } from 'node:fs/promises';
16	import * as path from 'pathe';
17	import {
18		ANGULAR_16_BROWSER_CELL,
19		ecosystemDispositionOf,
20		type AngularTargetCell,
21	} from '../../../frameworks/angular/src/index.ts';
22	import { refuse } from './refusals.ts';
23	
24	export type Lineage = 'angular' | 'react' | 'nextjs' | 'unknown';
25	
26	/** The reading this module writes when the tree does not state the fact. */
27	export const UNKNOWN = 'unknown' as const;
28	
29	export type PackageManagerReading = Readonly<{
30		/** `npm`, `yarn`, `pnpm`, `ambiguous` when several lockfiles are present, or `unknown`. */
31		manager: string;
32		/** The lockfiles actually found, by workspace-relative path. */
33		lockfiles: readonly string[];
34		/** The `packageManager` field the manifest declares, or `unknown`. */
35		declared: string;
36	}>;
37	
38	export type NodeEraReading = Readonly<{
39		/** The Node line the tree declares for itself, or `unknown`. */
40		declared: string;
41		/** Which file declared it, or `unknown`. */
42		source: string;
43	}>;
44	
45	export type CellVerdict = Readonly<{
46		package: string;
47		declaredRange: string;
48		/** `aligned`, `no-successor`, `successor-fork`, or `unknown` when the cell has no reading. */
49		verdict: string;
50		/** The cell's own words for the reading, or `unknown`. */
51		fact: string;
52		/** The range the cell writes for an aligned package, otherwise `unknown`. */
53		alignedRange: string;
54	}>;
55	
56	export type CellReadings = Readonly<{
57		/** The cell identifier, or `null` when the lineage publishes no cell registry. */
58		cell: string | null;
59		/** Why there is no cell, when there is none. */
60		reason: string | null;
61		verdicts: readonly CellVerdict[];
62		counts: Readonly<Record<string, number>>;
63	}>;
64	
65	export type ApplicationAnalysis = Readonly<{
66		lineage: Lineage;
67		/** The framework version range the manifest declares, or `unknown`. */
68		frameworkVersionDeclared: string;
69		/** The package the lineage was detected from, or `unknown`. */
70		detectedFrom: string;
71		/** The build tool the tree declares, or `unknown`. */
72		builder: string;
73		/** Where the builder reading came from, or `unknown`. */
74		builderSource: string;
75		nodeEra: NodeEraReading;
76		packageManager: PackageManagerReading;
77		cellReadings: CellReadings;
78		notEstablished: readonly string[];
79	}>;
80	
81	const NOT_ESTABLISHED: readonly string[] = Object.freeze([
82		'Detection reads declarations. Nothing here establishes that this application installs, compiles, builds, or behaves as it did on its era toolchain.',
83		'A cell verdict is a reading of a published registry, not an installation: a range written here has not been resolved against any lockfile by this record.',
84		'A dependency the cell has no reading for is reported `unknown`. `unknown` is not `supported` and it is not `unsupported`.',
85	]);
86	
87	export async function fileExists(file: string): Promise<boolean> {
88		try {
89			return (await stat(file)).isFile();
90		} catch {
91			return false;
92		}
93	}
94	
95	export async function directoryExists(directory: string): Promise<boolean> {
96		try {
97			return (await stat(directory)).isDirectory();
98		} catch {
99			return false;
100		}
101	}
102	
103	export async function readJsonFile(file: string): Promise<Record<string, unknown> | null> {
104		try {
105			const parsed = JSON.parse(await readFile(file, 'utf8')) as unknown;
106			return parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)
107				? (parsed as Record<string, unknown>)
108				: null;
109		} catch {
110			return null;
111		}
112	}
113	
114	function stringsOf(value: unknown): Readonly<Record<string, string>> {
115		if (value === null || typeof value !== 'object' || Array.isArray(value)) return {};
116		const entries: [string, string][] = [];
117		for (const [key, item] of Object.entries(value as Record<string, unknown>))
118			if (typeof item === 'string') entries.push([key, item]);
119		return Object.fromEntries(entries);
120	}
121	
122	/** Every declared dependency of a manifest, runtime and development alike. */
123	export function declaredDependencies(
124		manifest: Record<string, unknown> | null,
125	): Readonly<Record<string, string>> {
126		if (manifest === null) return {};
127		return Object.freeze({
128			...stringsOf(manifest.dependencies),
129			...stringsOf(manifest.devDependencies),
130		});
131	}
132	
133	/**
134	 * The Angular workspace build target, read from the workspace document rather
135	 * than assumed. A workspace that declares none is reported `unknown`.
136	 */
137	export function angularBuilderOf(workspace: Record<string, unknown> | null): string {
138		if (workspace === null) return UNKNOWN;
139		const projects = workspace.projects;
140		if (projects === null || typeof projects !== 'object') return UNKNOWN;
141		for (const project of Object.values(projects as Record<string, unknown>)) {
142			if (project === null || typeof project !== 'object') continue;
143			const record = project as Record<string, unknown>;
144			const targets = (record.architect ?? record.targets) as Record<string, unknown> | undefined;
145			if (targets === undefined || targets === null) continue;
146			const build = targets.build as Record<string, unknown> | undefined;
147			if (build === undefined || build === null) continue;
148			const builder = build.builder ?? build.executor;
149			if (typeof builder === 'string' && builder.length > 0) return builder;
150		}
151		return UNKNOWN;
152	}
153	
154	/**
155	 * The Angular `sourceRoot` declarations the workspace carries, in project
156	 * order. A workspace that declares none yields none, which is what makes the
157	 * operator ask for `--source-dir` instead of guessing `src`.
158	 */
159	export function angularSourceRoots(workspace: Record<string, unknown> | null): readonly string[] {
160		if (workspace === null) return Object.freeze([]);
161		const projects = workspace.projects;
162		if (projects === null || typeof projects !== 'object') return Object.freeze([]);
163		const roots: string[] = [];
164		for (const project of Object.values(projects as Record<string, unknown>)) {
165			if (project === null || typeof project !== 'object') continue;
166			const record = project as Record<string, unknown>;
167			const targets = (record.architect ?? record.targets) as Record<string, unknown> | undefined;
168			const hasBuild =
169				targets !== undefined && targets !== null && Object.hasOwn(targets, 'build');
170			if (!hasBuild) continue;
171			if (typeof record.sourceRoot === 'string' && record.sourceRoot.length > 0)
172				roots.push(record.sourceRoot);
173		}
174		return Object.freeze(roots);
175	}
176	
177	async function readNodeEra(root: string): Promise<NodeEraReading> {
178		for (const name of ['.nvmrc', '.node-version']) {
179			const file = path.join(root, name);
180			if (!(await fileExists(file))) continue;
181			const declared = (await readFile(file, 'utf8')).trim();
182			if (declared.length > 0) return Object.freeze({ declared, source: name });
183		}
184		const manifest = await readJsonFile(path.join(root, 'package.json'));
185		const engines = stringsOf(manifest?.engines);
186		if (typeof engines.node === 'string' && engines.node.length > 0)
187			return Object.freeze({ declared: engines.node, source: 'package.json#engines.node' });
188		return Object.freeze({ declared: UNKNOWN, source: UNKNOWN });
189	}
190	
191	const LOCKFILES: Readonly<Record<string, string>> = Object.freeze({
192		'package-lock.json': 'npm',
193		'npm-shrinkwrap.json': 'npm',
194		'yarn.lock': 'yarn',
195		'pnpm-lock.yaml': 'pnpm',
196	});
197	
198	async function readPackageManager(
199		root: string,
200		manifest: Record<string, unknown> | null,
201	): Promise<PackageManagerReading> {
202		const found: string[] = [];
203		const managers = new Set<string>();
204		for (const name of Object.keys(LOCKFILES).sort())
205			if (await fileExists(path.join(root, name))) {
206				found.push(name);
207				managers.add(LOCKFILES[name] as string);
208			}
209		const declared =
210			typeof manifest?.packageManager === 'string' && manifest.packageManager.length > 0
211				? manifest.packageManager
212				: UNKNOWN;
213		const manager =
214			managers.size === 1
215				? ([...managers][0] as string)
216				: managers.size > 1
217					? 'ambiguous'
218					: UNKNOWN;
219		return Object.freeze({ manager, lockfiles: Object.freeze(found), declared });
220	}
221	
222	/**
223	 * The cell's verdict on every package the application declares.
224	 *
225	 * Only the Angular target cell publishes a per-package registry, so a React or
226	 * Next.js tree is reported as having no cell rather than as having a cell that
227	 * read nothing. A declared package the registry does not carry is `unknown`.
228	 */
229	export function readCellVerdicts(
230		lineage: Lineage,
231		dependencies: Readonly<Record<string, string>>,
232		cell: AngularTargetCell = ANGULAR_16_BROWSER_CELL,
233	): CellReadings {
234		if (lineage !== 'angular')
235			return Object.freeze({
236				cell: null,
237				reason: 'The frozen React and Next.js adapters publish no target-cell package registry, so no per-package verdict exists for this lineage. Every declared dependency is unknown to the engine rather than accepted by it.',
238				verdicts: Object.freeze([]),
239				counts: Object.freeze({ unknown: Object.keys(dependencies).length }),
240			});
241		const verdicts: CellVerdict[] = [];
242		const counts: Record<string, number> = {
243			aligned: 0,
244			'no-successor': 0,
245			'successor-fork': 0,
246			unknown: 0,
247		};
248		for (const name of Object.keys(dependencies).sort()) {
249			const disposition = ecosystemDispositionOf(name, cell);
250			const verdict = disposition === null ? UNKNOWN : disposition.kind;
251			counts[verdict] = (counts[verdict] ?? 0) + 1;
252			verdicts.push({
253				package: name,
254				declaredRange: dependencies[name] as string,
255				verdict,
256				fact: disposition === null ? UNKNOWN : disposition.fact,
257				alignedRange:
258					disposition !== null && disposition.kind === 'aligned'
259						? disposition.range
260						: UNKNOWN,
261			});
262		}
263		return Object.freeze({
264			cell: cell.id,
265			reason: null,
266			verdicts: Object.freeze(verdicts),
267			counts: Object.freeze(counts),
268		});
269	}
270	
271	/** Refuse an application root that is not a directory carrying a manifest. */
272	export async function assertApplicationRoot(root: string): Promise<void> {
273		if (!(await directoryExists(root)))
274			refuse({
275				code: 'analyze.application-root-not-a-directory',
276				message: `Application root is not a directory: ${root}`,
277				stage: 'analyze',
278				origin: 'pipeline',
279			});
280		if (!(await fileExists(path.join(root, 'package.json'))))
281			refuse({
282				code: 'analyze.application-root-carries-no-manifest',
283				message: `Application root carries no package.json: ${root}`,
284				stage: 'analyze',
285				origin: 'pipeline',
286			});
287	}
288	
289	export async function analyzeApplication(
290		root: string,
291		cell: AngularTargetCell = ANGULAR_16_BROWSER_CELL,
292	): Promise<ApplicationAnalysis> {
293		await assertApplicationRoot(root);
294		const manifest = await readJsonFile(path.join(root, 'package.json'));
295		const dependencies = declaredDependencies(manifest);
296		const workspace = await readJsonFile(path.join(root, 'angular.json'));
297		const legacyWorkspace =
298			workspace === null ? await readJsonFile(path.join(root, '.angular-cli.json')) : null;
299		const lineage: Lineage = Object.hasOwn(dependencies, '@angular/core')
300			? 'angular'
301			: Object.hasOwn(dependencies, 'next')
302				? 'nextjs'
303				: Object.hasOwn(dependencies, 'react')
304					? 'react'
305					: 'unknown';
306		const detectedFrom =
307			lineage === 'angular'
308				? '@angular/core'
309				: lineage === 'nextjs'
310					? 'next'
311					: lineage === 'react'
312						? 'react'
313						: UNKNOWN;
314		const viteConfigs: string[] = [];
315		for (const name of ['vite.config.ts', 'vite.config.js', 'vite.config.mjs'])
316			if (await fileExists(path.join(root, name))) viteConfigs.push(name);
317		const angularBuilder = angularBuilderOf(workspace);
318		const builder =
319			lineage === 'angular'
320				? angularBuilder === UNKNOWN && legacyWorkspace !== null
321					? 'angular-cli-1.x (.angular-cli.json, no builder field)'
322					: angularBuilder
323				: Object.hasOwn(dependencies, 'react-scripts')
324					? 'react-scripts'
325					: viteConfigs.length > 0
326						? 'vite'
327						: Object.hasOwn(dependencies, 'next')
328							? 'next'
329							: UNKNOWN;
330		const builderSource =
331			lineage === 'angular'
332				? workspace !== null
333					? 'angular.json'
334					: legacyWorkspace !== null
335						? '.angular-cli.json'
336						: UNKNOWN
337				: builder === 'react-scripts' || builder === 'next'
338					? 'package.json'
339					: builder === 'vite'
340						? (viteConfigs[0] as string)
341						: UNKNOWN;
342		return Object.freeze({
343			lineage,
344			frameworkVersionDeclared:
345				detectedFrom === UNKNOWN ? UNKNOWN : (dependencies[detectedFrom] ?? UNKNOWN),
346			detectedFrom,
347			builder,
348			builderSource,
349			nodeEra: await readNodeEra(root),
350			packageManager: await readPackageManager(root, manifest),
351			cellReadings: readCellVerdicts(lineage, dependencies, cell),
352			notEstablished: NOT_ESTABLISHED,
353		});
354	}
355	
356	/**
357	 * Every workspace-relative path below `directory`, in the order a depth-first
358	 * walk that sorts each directory's own entries by name produces. Installed
359	 * packages and Git metadata are never walked.
360	 */
361	export async function workspacePathsBelow(directory: string, root: string): Promise<string[]> {
362		const paths: string[] = [];
363		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
364			left.name < right.name ? -1 : 1,
365		)) {
366			if (entry.name === 'node_modules' || entry.name === '.git') continue;
367			const item = path.join(directory, entry.name);
368			if (entry.isDirectory()) {
369				paths.push(...(await workspacePathsBelow(item, root)));
370				continue;
371			}
372			if (entry.isFile()) paths.push(path.relative(root, item));
373		}
374		return paths;
375	}
