437		const lines = [
438			`application: ${record.id ?? ''} (${record.idSource ?? ''})`,
439			`frontend root: ${record.frontendRoot ?? ''} (${record.frontendRootSource ?? ''})`,
440			`pinned revision: ${record.pin?.commitSha ?? ''} (${record.pin?.commitShaSource ?? ''}${
441				record.pin?.commitShaReadFrom === null || record.pin?.commitShaReadFrom === undefined
442					? ''
443					: ` from ${record.pin.commitShaReadFrom}`
444			})`,
445			`repository: ${record.pin?.repository ?? 'not declared'}; ref: ${record.pin?.ref ?? 'not declared'}`,
446			`tree: ${String(record.tree?.files ?? 0)} file(s), ${String(record.tree?.bytes ?? 0)} byte(s), manifest ${(record.tree?.normalizedManifestSha256 ?? '').slice(0, 12)}`,
447			`lineage: ${record.detected?.lineage ?? ''}; builder: ${record.detected?.builder ?? ''}; node era: ${record.detected?.nodeEra.declared ?? ''}`,
448			`licence: ${record.licence?.identifier ?? ''} (${record.licence?.identifierSource ?? ''})`,
449			record.closure === null
450				? `closure: none — ${record.closureReason ?? ''}`
451				: `closure: ${record.closure.lockState.file} — ${String(record.closure.counts.lockedPlacements)} placement(s), ${String(record.closure.counts.distinctNameVersionPairs)} distinct name@version`,
452			'',
453		];
454		for (const line of [...record.notEstablished, ...(record.licence?.notEstablished ?? [])])
455			lines.push(`not established: ${line}`);
456		return `${lines.join('\n')}\n`;
457	}
