1	/**
2	 * The `license-at-pin` stage: what licence the application carries at the
3	 * revision this pipeline pinned it to.
4	 *
5	 * Today this reading is hand-authored. `evidence/ingests/react-papercups-v1-0-0/license.json`
6	 * is a `versionless.legacy-corpus-rights.v1` document somebody wrote after
7	 * looking at the tree, and no code in this repository produces one. That is a
8	 * human intervention inside a run the pipeline is meant to complete unattended,
9	 * and it is the reason an application the pipeline has never seen cannot be
10	 * admitted without an operator reading a licence file for it.
11	 *
12	 * This stage reads it instead, and it reads it the way the rest of the operator
13	 * surface reads things: it states what the bytes say, it digests what it read,
14	 * and it refuses by name rather than filling a gap with a plausible identifier.
15	 *
16	 * The declared-policy shape is the one the install stage set. The identifier is
17	 * *observed* by default — matched against the licence texts this stage can
18	 * recognise — and `--license <spdx>` is the declaration that settles a tree this
19	 * stage cannot read. The default is refusing: a licence file whose text matches
20	 * nothing here, or a file that disagrees with the manifest's own `license`
21	 * field, is a named refusal rather than a guess, because "which licence this
22	 * source is under" is not a question a migration tool may answer approximately.
23	 *
24	 * Nothing here is a legal reading. The record says so in its own words, in the
25	 * same terms the sealed hand-authored record already uses.
26	 */
27	
28	import { readFile, readdir } from 'node:fs/promises';
29	import * as path from 'pathe';
30	import { sha256 } from '../../../core/src/receipts/canonicalize.ts';
31	import { gitBlobId } from '../fixture/legacy-candidate-ingest.ts';
32	import { readJsonFile } from './analyze.ts';
33	import { refuse } from './refusals.ts';
34	
35	export const LICENSE_AT_PIN_SCHEMA = 'versionless.license-at-pin.v1';
36	
37	/**
38	 * The licence file names this stage looks for at the source root.
39	 *
40	 * Both spellings, because the corpus carries both: the sealed papercups record
41	 * names `LICENSE` and the sealed react-realworld ingest names `LICENSE.md`.
42	 */
43	export const LICENCE_FILENAMES: readonly string[] = Object.freeze([
44		'LICENSE',
45		'LICENSE.md',
46		'LICENSE.txt',
47		'LICENCE',
48		'LICENCE.md',
49		'LICENCE.txt',
50		'COPYING',
51		'COPYING.md',
52	]);
53	
54	/**
55	 * The licence texts this stage reads, each as the runs of text that must be
56	 * present and the runs that must be absent for the identifier to be stated.
57	 *
58	 * Every entry names an exact identifier, never a family: `BSD` and `GPL` are
59	 * not readings, because a record that says `GPL` has not said which obligations
60	 * apply. Where the variants are separated by a line in the canonical text, the
61	 * variants are listed separately; where they are not, the text is unrecognised
62	 * and the stage refuses. This is a text reading, not a parser — a reworded,
63	 * translated, amended or dual licence matches nothing here by design.
64	 */
65	const LICENCE_SIGNATURES: readonly Readonly<{
66		identifier: string;
67		requires: readonly string[];
68		absent: readonly string[];
69	}>[] = Object.freeze([
70		Object.freeze({
71			identifier: 'MIT',
72			requires: Object.freeze([
73				'Permission is hereby granted, free of charge, to any person obtaining a copy',
74			]),
75			absent: Object.freeze([]),
76		}),
77		Object.freeze({
78			identifier: 'Apache-2.0',
79			requires: Object.freeze(['Apache License', 'Version 2.0']),
80			absent: Object.freeze([]),
81		}),
82		Object.freeze({
83			identifier: 'ISC',
84			requires: Object.freeze([
85				'Permission to use, copy, modify, and/or distribute this software',
86			]),
87			absent: Object.freeze([]),
88		}),
89		Object.freeze({
90			identifier: 'MPL-2.0',
91			requires: Object.freeze(['Mozilla Public License Version 2.0']),
92			absent: Object.freeze([]),
93		}),
94		Object.freeze({
95			identifier: 'Unlicense',
96			requires: Object.freeze([
97				'This is free and unencumbered software released into the public domain',
98			]),
99			absent: Object.freeze([]),
100		}),
101		Object.freeze({
102			identifier: 'BSD-3-Clause',
103			requires: Object.freeze([
104				'Redistribution and use in source and binary forms',
105				'Neither the name of',
106			]),
107			absent: Object.freeze([]),
108		}),
109		Object.freeze({
110			identifier: 'BSD-2-Clause',
111			requires: Object.freeze(['Redistribution and use in source and binary forms']),
112			absent: Object.freeze(['Neither the name of']),
113		}),
114		Object.freeze({
115			identifier: 'GPL-3.0',
116			requires: Object.freeze(['GNU GENERAL PUBLIC LICENSE', 'Version 3']),
117			absent: Object.freeze([]),
118		}),
119		Object.freeze({
120			identifier: 'GPL-2.0',
121			requires: Object.freeze(['GNU GENERAL PUBLIC LICENSE', 'Version 2']),
122			absent: Object.freeze([]),
123		}),
124		Object.freeze({
125			identifier: 'AGPL-3.0',
126			requires: Object.freeze(['GNU AFFERO GENERAL PUBLIC LICENSE', 'Version 3']),
127			absent: Object.freeze([]),
128		}),
129		Object.freeze({
130			identifier: 'LGPL-3.0',
131			requires: Object.freeze(['GNU LESSER GENERAL PUBLIC LICENSE', 'Version 3']),
132			absent: Object.freeze([]),
133		}),
134		Object.freeze({
135			identifier: 'LGPL-2.1',
136			requires: Object.freeze(['GNU LESSER GENERAL PUBLIC LICENSE', 'Version 2.1']),
137			absent: Object.freeze([]),
138		}),
139	]);
140	
141	/** The three clauses the sealed rights record checks a licence text for. */
142	const PERMISSION_GRANT_PHRASES: readonly string[] = Object.freeze([
143		'Permission is hereby granted',
144		'Permission to use, copy, modify',
145		'Redistribution and use in source and binary forms',
146		'You may obtain a copy of the License',
147		'hereby grants You a world-wide',
148		'released into the public domain',
149		'copy, distribute and modify',
150	]);
151	
152	const NOTICE_RETENTION_PHRASES: readonly string[] = Object.freeze([
153		'above copyright notice',
154		'copyright notice and this permission notice',
155		'retain the above copyright notice',
156		'must retain',
157		'You must give any other recipients',
158		'must include a copy',
159	]);
160	
161	const WARRANTY_DISCLAIMER_PHRASES: readonly string[] = Object.freeze([
162		'WITHOUT WARRANTY',
163		'WITHOUT WARRANTIES',
164		'AS IS',
165		'DISCLAIMS ALL WARRANTIES',
166	]);
167	
168	const carries = (text: string, phrases: readonly string[]): boolean =>
169		phrases.some((phrase) => text.includes(phrase));
170	
171	export type LicenceArtifact = Readonly<{
172		/** Path relative to the source root, as the record reads it. */
173		path: string;
174		role: 'repository-root-licence' | 'frontend-manifest';
175		gitBlobSha: string;
176		bytes: number;
177		sha256: string;
178		/** The first non-empty line of a licence file, or `null` for a manifest. */
179		firstLine: string | null;
180		permissionGrantPresent: boolean | null;
181		noticeRetentionClausePresent: boolean | null;
182		warrantyDisclaimerPresent: boolean | null;
183		/** The `license` field of a manifest, or `null` for a licence file. */
184		licenseField: string | null;
185	}>;
186	
187	/**
188	 * How the identifier was arrived at.
189	 *
190	 * `observed` means this stage read it out of the licence text at the pin.
191	 * `declared` means an operator supplied it with `--license` because the text
192	 * matched nothing this stage recognises. The two are never merged: a reader has
193	 * to be able to tell a reading from a declaration.
194	 */
195	export type LicenceIdentifierSource = 'observed' | 'declared';
196	
197	export type LicencePolicy = Readonly<{
198		/** The identifier an operator declares for a text this stage cannot read. */
199		declaredIdentifier: string | null;
200	}>;
201	
202	export const DEFAULT_LICENCE_POLICY: LicencePolicy = Object.freeze({ declaredIdentifier: null });
203	
204	export type LicenceAtPinRecord = Readonly<{
205		stage: 'license-at-pin';
206		schemaVersion: string;
207		ran: boolean;
208		/** Why the stage did not run, when it did not. */
209		reason: string | null;
210		identifier: string | null;
211		identifierSource: LicenceIdentifierSource | null;
212		/** The basis, in the stage's own words, for the identifier it recorded. */
213		identifierBasis: string | null;
214		copyrightNotice: string | null;
215		/** The `license` field the frontend manifest declares, or `null`. */
216		manifestLicenseField: string | null;
217		artifacts: readonly LicenceArtifact[];
218		/** Licence files found at the source root. */
219		licenceFilesAtRoot: readonly string[];
220		notEstablished: readonly string[];
221	}>;
222	
223	const LICENCE_NOT_ESTABLISHED: readonly string[] = Object.freeze([
224		'This is a record of the licence text present at the pinned revision. It is not a legal opinion, a licence-compatibility finding, or legal approval.',
225		'No licence determination is made for the transitive dependency closure. Each dependency carries its own terms and this stage evaluates none of them.',
226		'The identifier is matched against the canonical wording of the licences this stage recognises. A reworded, translated, amended or dual licence is refused rather than matched to the nearest one, so an absent refusal is not evidence that no such amendment exists.',
227		'Only the source root is read for licence files. A licence carried further down the tree, a per-directory notice, and a vendored third-party licence are outside this reading.',
228		'`identifierSource: declared` means an operator supplied the identifier. This stage did not read it and does not corroborate it.',
229	]);
230	
231	/** The record for a stage the run did not ask for. */
232	export function licenceNotRequested(reason: string): LicenceAtPinRecord {
233		return Object.freeze({
234			stage: 'license-at-pin',
235			schemaVersion: LICENSE_AT_PIN_SCHEMA,
236			ran: false,
237			reason,
238			identifier: null,
239			identifierSource: null,
240			identifierBasis: null,
241			copyrightNotice: null,
242			manifestLicenseField: null,
243			artifacts: Object.freeze([]),
244			licenceFilesAtRoot: Object.freeze([]),
245			notEstablished: LICENCE_NOT_ESTABLISHED,
246		});
247	}
248	
249	/** The first non-empty line of a licence text. */
250	export function firstLineOf(text: string): string {
251		for (const line of text.split('\n')) {
252			const trimmed = line.trim();
253			if (trimmed !== '') return trimmed;
254		}
255		return '';
256	}
257	
258	/** The copyright line a licence text carries, or `null` when it carries none. */
259	export function copyrightNoticeOf(text: string): string | null {
260		for (const line of text.split('\n')) {
261			const trimmed = line.trim();
262			if (trimmed.startsWith('Copyright') && trimmed !== 'Copyright') return trimmed;
263		}
264		return null;
265	}
266	
267	/**
268	 * The identifier a licence text states, or `null` when it states none this
269	 * stage recognises. A text matching more than one signature is `null` as well:
270	 * two identifiers in one file is a reading this stage will not make.
271	 */
272	export function licenceIdentifierOf(text: string): string | null {
273		const matched = LICENCE_SIGNATURES.filter(
274			(signature) =>
275				signature.requires.every((phrase) => text.includes(phrase)) &&
276				signature.absent.every((phrase) => !text.includes(phrase)),
277		);
278		if (matched.length !== 1) return null;
279		return (matched[0] as (typeof LICENCE_SIGNATURES)[number]).identifier;
280	}
281	
282	/** Licence file names present at the source root, in the declared order. */
283	export async function licenceFilesAtRoot(sourceRoot: string): Promise<readonly string[]> {
284		let entries: string[];
285		try {
286			entries = (await readdir(sourceRoot, { withFileTypes: true }))
287				.filter((entry) => entry.isFile())
288				.map((entry) => entry.name);
289		} catch {
290			return Object.freeze([]);
291		}
292		return Object.freeze(LICENCE_FILENAMES.filter((name) => entries.includes(name)));
293	}
294	
295	/**
296	 * Read the licence at the pinned source, or refuse by name.
297	 *
298	 * `sourceRoot` is the repository root at the pin — the sealed records read the
299	 * repository-root licence, not the frontend subdirectory's. `manifestFile` is
300	 * the frontend manifest whose `license` field the record carries beside it.
301	 */
302	export async function readLicenceAtPin(
303		sourceRoot: string,
304		manifestFile: string | null = null,
305		policy: LicencePolicy = DEFAULT_LICENCE_POLICY,
306	): Promise<LicenceAtPinRecord> {
307		const found = await licenceFilesAtRoot(sourceRoot);
308		if (found.length === 0)
309			refuse({
310				code: 'license-at-pin.licence-file-absent',
311				message: `License at pin: the source root carries none of ${LICENCE_FILENAMES.join(', ')}, so there is no licence text to read at the pinned revision. This flow records the licence it observed rather than inferring one from a manifest field, and it does not admit an application whose terms it never read.`,
312				stage: 'license-at-pin',
313				origin: 'pipeline',
314			});
315		const artifacts: LicenceArtifact[] = [];
316		const readings = new Map<string, string | null>();
317		let copyrightNotice: string | null = null;
318		for (const name of found) {
319			const bytes = await readFile(path.join(sourceRoot, name));
320			const text = bytes.toString('utf8');
321			const identifier = licenceIdentifierOf(text);
322			readings.set(name, identifier);
323			copyrightNotice = copyrightNotice ?? copyrightNoticeOf(text);
324			artifacts.push(
325				Object.freeze({
326					path: name,
327					role: 'repository-root-licence' as const,
328					gitBlobSha: gitBlobId(bytes),
329					bytes: bytes.byteLength,
330					sha256: sha256(bytes),
331					firstLine: firstLineOf(text),
332					permissionGrantPresent: carries(text, PERMISSION_GRANT_PHRASES),
333					noticeRetentionClausePresent: carries(text, NOTICE_RETENTION_PHRASES),
334					warrantyDisclaimerPresent: carries(text, WARRANTY_DISCLAIMER_PHRASES),
335					licenseField: null,
336				}),
337			);
338		}
339		let manifestLicenseField: string | null = null;
340		if (manifestFile !== null) {
341			const manifest = await readJsonFile(manifestFile);
342			if (manifest !== null) {
343				if (typeof manifest.license === 'string' && manifest.license !== '')
344					manifestLicenseField = manifest.license;
345				const bytes = await readFile(manifestFile);
346				artifacts.push(
347					Object.freeze({
348						path: path.relative(sourceRoot, manifestFile),
349						role: 'frontend-manifest' as const,
350						gitBlobSha: gitBlobId(bytes),
351						bytes: bytes.byteLength,
352						sha256: sha256(bytes),
353						firstLine: null,
354						permissionGrantPresent: null,
355						noticeRetentionClausePresent: null,
356						warrantyDisclaimerPresent: null,
357						licenseField: manifestLicenseField,
358					}),
359				);
360			}
361		}
362		const observed = [...new Set([...readings.values()].filter((value) => value !== null))];
363		if (policy.declaredIdentifier === null && observed.length > 1)
364			refuse({
365				code: 'license-at-pin.root-licence-files-state-different-identifiers',
366				message: `License at pin: the source root carries ${String(found.length)} licence files stating ${observed.join(' and ')}. Which one the application is offered under is a reading this flow will not make; declare it with --license <identifier> if the pinned source settles it, and this record will say the identifier was declared rather than observed.`,
367				stage: 'license-at-pin',
368				origin: 'pipeline',
369			});
370		const single = observed[0] ?? null;
371		if (policy.declaredIdentifier === null && single === null)
372			refuse({
373				code: 'license-at-pin.identifier-not-recognised',
374				message: `License at pin: ${found.join(', ')} is present at the pinned revision and its text matches none of the licences this stage reads verbatim (${LICENCE_SIGNATURES.map((signature) => signature.identifier).join(', ')}). A licence this flow cannot read is not a licence it will guess at; declare it with --license <identifier>, and this record will say the identifier was declared rather than observed.`,
375				stage: 'license-at-pin',
376				origin: 'pipeline',
377			});
378		if (
379			policy.declaredIdentifier === null &&
380			manifestLicenseField !== null &&
381			single !== null &&
382			manifestLicenseField !== single
383		)
384			refuse({
385				code: 'license-at-pin.manifest-field-conflicts-with-licence-text',
386				message: `License at pin: the licence text at the pinned revision reads ${single} and the manifest declares ${manifestLicenseField}. This flow does not pick between a file and a field that disagree; declare the identifier with --license <identifier> to settle it, and this record will say it was declared.`,
387				stage: 'license-at-pin',
388				origin: 'pipeline',
389			});
390		const identifier = policy.declaredIdentifier ?? (single as string);
391		const identifierSource: LicenceIdentifierSource =
392			policy.declaredIdentifier === null ? 'observed' : 'declared';
393		return Object.freeze({
394			stage: 'license-at-pin',
395			schemaVersion: LICENSE_AT_PIN_SCHEMA,
396			ran: true,
397			reason: null,
398			identifier,
399			identifierSource,
400			/**
401			 * The observed wording is the sealed hand-authored record's own —
402			 * `evidence/ingests/react-papercups-v1-0-0/license.json` reads
403			 * "verbatim MIT text in the repository root LICENSE file at the pinned
404			 * revision" — so a record this stage derives and a record somebody wrote
405			 * can be compared rather than merely both being about a licence.
406			 */
407			identifierBasis:
408				identifierSource === 'observed'
409					? `verbatim ${identifier} text in the repository root ${found.join(', ')} file at the pinned revision`
410					: `declared with --license ${identifier}; the text in ${found.join(', ')} at the pinned revision was not read as an identifier by this stage`,
411			copyrightNotice,
412			manifestLicenseField,
413			artifacts: Object.freeze(artifacts),
414			licenceFilesAtRoot: found,
415			notEstablished: LICENCE_NOT_ESTABLISHED,
416		});
417	}
418	
419	/** The licence record as an operator reads it. */
420	export function renderLicenceAtPin(record: LicenceAtPinRecord): string {
421		const lines = record.ran
422			? [
423					`licence: ${record.identifier ?? ''} (${record.identifierSource ?? ''})`,
424					`basis: ${record.identifierBasis ?? ''}`,
425					`copyright: ${record.copyrightNotice ?? 'none stated'}`,
426					`manifest license field: ${record.manifestLicenseField ?? 'none declared'}`,
427					'',
428				]
429			: [`licence: not read — ${record.reason ?? ''}`, ''];
430		for (const artifact of record.artifacts)
431			lines.push(
432				`  ${artifact.path} (${artifact.role}) ${artifact.sha256.slice(0, 12)} ${String(artifact.bytes)} bytes`,
433			);
434		lines.push('');
435		for (const line of record.notEstablished) lines.push(`not established: ${line}`);
436		return `${lines.join('\n')}\n`;
437	}
