292	type Node = Record<string, unknown> & { type: string; start: number; end: number };
293	
294	function isNode(value: unknown): value is Node {
295		return (
296			value !== null &&
297			typeof value === 'object' &&
298			typeof (value as { type?: unknown }).type === 'string'
299		);
300	}
301	
302	/** Collapse every whitespace run to one space, so a guard reads on one line. */
303	export function collapseWhitespace(value: string): string {
304		const parts: string[] = [];
305		let current = '';
306		for (const character of value) {
307			const white =
308				character === ' ' ||
309				character === '\t' ||
310				character === '\n' ||
311				character === '\r' ||
312				character === '\f' ||
313				character === '\v';
314			if (white) {
315				if (current !== '') parts.push(current);
316				current = '';
317				continue;
318			}
319			current += character;
320		}
321		if (current !== '') parts.push(current);
322		return parts.join(' ');
323	}
324	
325	type Segment = Readonly<{ kind: 'text' | 'expression'; value: string }>;
326	
327	function messageSegments(node: Node | undefined, source: string): Segment[] {
328		if (node === undefined) return [];
329		if (node.type === 'Literal' && typeof node.value === 'string')
330			return [{ kind: 'text', value: node.value }];
331		if (node.type === 'TemplateLiteral') {
332			const quasis = (node.quasis ?? []) as Node[];
333			const expressions = (node.expressions ?? []) as Node[];
334			const segments: Segment[] = [];
335			for (let index = 0; index < quasis.length; index += 1) {
336				const quasi = quasis[index] as Node | undefined;
337				const cooked = (quasi?.value as { cooked?: string } | undefined)?.cooked ?? '';
338				if (cooked !== '') segments.push({ kind: 'text', value: cooked });
339				const expression = expressions[index];
340				if (expression !== undefined)
341					segments.push({
342						kind: 'expression',
343						value: collapseWhitespace(source.slice(expression.start, expression.end)),
344					});
345			}
346			return segments;
347		}
348		if (node.type === 'BinaryExpression' && node.operator === '+')
349			return [
350				...messageSegments(node.left as Node | undefined, source),
351				...messageSegments(node.right as Node | undefined, source),
352			];
353		return [{ kind: 'expression', value: collapseWhitespace(source.slice(node.start, node.end)) }];
354	}
355	
356	function renderSegments(segments: readonly Segment[]): string {
357		return segments
358			.map((segment) => (segment.kind === 'text' ? segment.value : `\${${segment.value}}`))
359			.join('');
360	}
361	
362	function lineOf(source: string, offset: number): number {
363		let line = 1;
364		for (let index = 0; index < offset && index < source.length; index += 1)
365			if (source[index] === '\n') line += 1;
366		return line;
367	}
368	
369	const FUNCTION_TYPES: readonly string[] = Object.freeze([
370		'FunctionDeclaration',
371		'FunctionExpression',
372		'ArrowFunctionExpression',
373	]);
374	
375	function enclosingName(ancestors: readonly Node[]): string {
376		for (let index = ancestors.length - 1; index >= 0; index -= 1) {
377			const node = ancestors[index] as Node;
378			if (node.type === 'FunctionDeclaration') {
379				const id = node.id as Node | undefined;
380				const name = id === undefined ? null : (id.name as string | undefined);
381				if (name !== undefined && name !== null) return name;
382			}
383			if (node.type === 'VariableDeclarator') {
384				const id = node.id as Node | undefined;
385				const name = id === undefined ? null : (id.name as string | undefined);
386				if (name !== undefined && name !== null) return name;
387			}
388			if (node.type === 'MethodDefinition' || node.type === 'Property') {
389				const key = node.key as Node | undefined;
390				const name = key === undefined ? null : (key.name as string | undefined);
391				if (name !== undefined && name !== null) return name;
392			}
393		}
394		return 'module scope';
395	}
396	
397	function guardOf(
398		ancestors: readonly Node[],
399		site: Node,
400		source: string,
401	): { condition: string; conditionForm: CensusEntry['conditionForm'] } {
402		for (let index = ancestors.length - 1; index >= 0; index -= 1) {
403			const node = ancestors[index] as Node;
404			if (FUNCTION_TYPES.includes(node.type)) break;
405			if (node.type !== 'IfStatement') continue;
406			const test = node.test as Node;
407			const consequent = node.consequent as Node | undefined;
408			const inConsequent =
409				consequent !== undefined &&
410				site.start >= consequent.start &&
411				site.end <= consequent.end;
412			return {
413				condition: collapseWhitespace(source.slice(test.start, test.end)),
414				conditionForm: inConsequent ? 'if-consequent' : 'if-alternate',
415			};
416		}
417		return {
418			condition: `unconditional within ${enclosingName(ancestors)}`,
419			conditionForm: 'unconditional',
420		};
421	}
422	
423	const SLUG_LIMIT = 64;
424	
425	/** A stable, readable identifier derived from the site's own first words. */
426	export function slugOf(value: string): string {
427		let slug = '';
428		let pendingSeparator = false;
429		for (const character of value.toLowerCase()) {
430			const code = character.charCodeAt(0);
431			const alphanumeric = (code >= 97 && code <= 122) || (code >= 48 && code <= 57);
432			if (!alphanumeric) {
433				pendingSeparator = slug !== '';
434				continue;
435			}
436			if (pendingSeparator) {
437				if (slug.length >= SLUG_LIMIT) break;
438				slug += '-';
439				pendingSeparator = false;
440			}
441			if (slug.length >= SLUG_LIMIT) break;
442			slug += character;
443		}
444		return slug === '' ? 'unnamed' : slug;
445	}
446	
447	async function readEntries(directory: string) {
448		try {
449			return await readdir(directory, { withFileTypes: true });
450		} catch {
451			return [];
452		}
453	}
454	
455	async function typeScriptFilesBelow(directory: string): Promise<string[]> {
456		const files: string[] = [];
457		const entries = await readEntries(directory);
458		for (const entry of entries.sort((left, right) => (left.name < right.name ? -1 : 1))) {
459			if (
460				entry.name === 'node_modules' ||
461				entry.name === '.git' ||
462				entry.name === 'dist' ||
463				entry.name === 'test'
464			)
465				continue;
466			const item = path.join(directory, entry.name);
467			if (entry.isDirectory()) {
468				files.push(...(await typeScriptFilesBelow(item)));
469				continue;
470			}
471			if (entry.isFile() && path.extname(entry.name) === '.ts') files.push(item);
472		}
473		return files;
474	}
475	
476	type Site = Readonly<{
477		node: Node;
478		ancestors: readonly Node[];
479		kind: 'refuse-call' | 'throw-error';
480		argument: Node | undefined;
481		properties: Readonly<Record<string, Node>>;
482	}>;
483	
484	function propertiesOf(node: Node | undefined): Readonly<Record<string, Node>> {
485		if (node === undefined || node.type !== 'ObjectExpression') return {};
486		const record: Record<string, Node> = {};
487		for (const property of (node.properties ?? []) as Node[]) {
488			if (property.type !== 'Property') continue;
489			const key = property.key as Node | undefined;
490			const name = key === undefined ? undefined : (key.name as string | undefined);
491			const value = property.value as Node | undefined;
492			if (name !== undefined && value !== undefined) record[name] = value;
493		}
494		return record;
495	}
496	
497	type RecordedSite = Readonly<{ node: Node; callee: string; argument: Node | undefined }>;
498	
499	/**
500	 * Call sites named `refuse` or `refused` inside a frozen subtree.
501	 *
502	 * These are refusals the adapters *record* rather than throw — a local helper
503	 * appends a reason to a per-file refusal list, and the caller decides what to
504	 * do with it. They do not carry the pipeline's `{ code, message, stage, origin }`
505	 * shape, so the census does not pretend to have read one. What it does is count
506	 * and locate them, so the gap is a number instead of an absence.
507	 */
508	const RECORDED_REFUSAL_CALLEES: readonly string[] = Object.freeze(['refuse', 'refused']);
509	
510	function collectSites(
511		root: Node,
512		structured: boolean,
513	): { sites: Site[]; recorded: RecordedSite[] } {
514		const sites: Site[] = [];
515		const recorded: RecordedSite[] = [];
516		const walk = (node: Node, ancestors: Node[]): void => {
517			if (node.type === 'ThrowStatement') {
518				const argument = node.argument as Node | undefined;
519				const callee =
520					argument === undefined ? undefined : (argument.callee as Node | undefined);
521				if (
522					argument?.type === 'NewExpression' &&
523					callee?.type === 'Identifier' &&
524					callee.name === 'Error'
525				)
526					sites.push({
527						node,
528						ancestors: [...ancestors],
529						kind: 'throw-error',
530						argument: ((argument.arguments ?? []) as Node[])[0],
531						properties: {},
532					});
533			}
534			if (node.type === 'CallExpression') {
535				const callee = node.callee as Node | undefined;
536				const name = callee?.type === 'Identifier' ? (callee.name as string) : null;
537				if (name !== null && RECORDED_REFUSAL_CALLEES.includes(name)) {
538					const args = (node.arguments ?? []) as Node[];
539					if (structured && name === 'refuse')
540						sites.push({
541							node,
542							ancestors: [...ancestors],
543							kind: 'refuse-call',
544							argument: args[0],
545							properties: propertiesOf(args[0]),
546						});
547					else recorded.push({ node, callee: name, argument: args[args.length - 1] });
548				}
549			}
550			ancestors.push(node);
551			for (const key of Object.keys(node)) {
552				if (key === 'type' || key === 'start' || key === 'end') continue;
553				const value = node[key];
554				if (Array.isArray(value)) {
555					for (const item of value) if (isNode(item)) walk(item, ancestors);
556					continue;
557				}
558				if (isNode(value)) walk(value, ancestors);
559			}
560			ancestors.pop();
561		};
562		walk(root, []);
563		return { sites, recorded };
564	}
565	
566	function staticStringOf(node: Node | undefined, source: string): string | null {
567		const segments = messageSegments(node, source);
568		if (segments.length === 0) return null;
569		return segments.every((segment) => segment.kind === 'text') ? renderSegments(segments) : null;
570	}
571	
572	const compareEntries = (left: CensusEntry, right: CensusEntry): number => {
573		if (left.file !== right.file) return left.file < right.file ? -1 : 1;
574		return left.line - right.line;
575	};
576	
577	/** Derive the census from the checkout. Frozen paths are read, never written. */
578	export async function buildRefusalCensus(rootDir = '.'): Promise<RefusalCensus> {
579		const root = path.resolve(rootDir);
580		const modules = new Map(CENSUS_MODULES.map((module) => [module.file, module]));
581		const entries: CensusEntry[] = [];
582		const recordedRefusals: RecordedRefusal[] = [];
583		const usedCodes = new Map<string, number>();
584		let filesScanned = 0;
585		const unlisted: string[] = [];
586		for (const scanned of CENSUS_ROOTS) {
587			const scanRoot = path.join(root, scanned.root);
588			for (const file of await typeScriptFilesBelow(scanRoot)) {
589				const relative = path.relative(root, file);
590				const source = await readFile(file, 'utf8');
591				filesScanned += 1;
592				const collected = collectSites(
593					analyze(source, { path: relative }).ast as unknown as Node,
594					scanned.origin === 'pipeline',
595				);
596				for (const site of collected.recorded) {
597					const segments = messageSegments(site.argument, source);
598					if (segments.length === 0) continue;
599					recordedRefusals.push(
600						Object.freeze({
601							callee: site.callee,
602							message: renderSegments(segments),
603							messageForm: segments.every((segment) => segment.kind === 'text')
604								? ('static' as const)
605								: ('composed' as const),
606							origin: scanned.origin,
607							file: relative,
608							line: lineOf(source, site.node.start),
609							enclosing: 'recorded through a local helper',
610						}),
611					);
612				}
613				const sites = collected.sites;
614				if (sites.length === 0) continue;
615				const module = modules.get(relative);
616				if (module === undefined) {
617					unlisted.push(relative);
618					continue;
619				}
620				for (const site of sites) {
621					const messageNode =
622						site.kind === 'refuse-call' ? site.properties.message : site.argument;
623					const segments = messageSegments(messageNode, source);
624					const message = renderSegments(segments);
625					const staticSegments = segments
626						.filter((segment) => segment.kind === 'text')
627						.map((segment) => segment.value.trim())
628						.filter((segment) => segment !== '');
629					const declaredCode =
630						site.kind === 'refuse-call'
631							? staticStringOf(site.properties.code, source)
632							: null;
633					const declaredStage =
634						site.kind === 'refuse-call'
635							? staticStringOf(site.properties.stage, source)
636							: null;
637					const declaredOrigin =
638						site.kind === 'refuse-call'
639							? staticStringOf(site.properties.origin, source)
640							: null;
641					const stem = path.basename(relative, '.ts');
642					const fallback = `${module.origin === 'pipeline' ? 'pipeline' : 'frozen'}.${stem}.${slugOf(staticSegments[0] ?? message)}`;
643					const baseCode = declaredCode ?? fallback;
644					const seen = usedCodes.get(baseCode) ?? 0;
645					usedCodes.set(baseCode, seen + 1);
646					const code = seen === 0 ? baseCode : `${baseCode}-${String(seen + 1)}`;
647					const classification: CensusEntry['classification'] =
648						site.kind === 'refuse-call'
649							? 'refusal'
650							: module.origin === 'pipeline'
651								? 'defect'
652								: (staticSegments[0] ?? '').startsWith('Refused:')
653									? 'refusal'
654									: 'unclassified';
655					const guard = guardOf(site.ancestors, site.node, source);
656					entries.push(
657						Object.freeze({
658							code,
659							message,
660							messageForm: segments.every((segment) => segment.kind === 'text')
661								? ('static' as const)
662								: ('composed' as const),
663							staticSegments: Object.freeze(staticSegments),
664							classification,
665							condition: guard.condition,
666							conditionForm: guard.conditionForm,
667							origin:
668								declaredOrigin === 'frozen-adapter' || declaredOrigin === 'pipeline'
669									? declaredOrigin
670									: module.origin,
671							stage: declaredStage ?? module.stage,
672							stageBasis: module.stageBasis,
673							file: relative,
674							line: lineOf(source, site.node.start),
675							enclosing: enclosingName(site.ancestors),
676						}),
677					);
678				}
679			}
680		}
681		if (unlisted.length > 0)
682			throw new Error(
683				`refusal-census: ${String(unlisted.length)} scanned file(s) raise refusals and are not declared in CENSUS_MODULES: ${unlisted.sort().join(', ')}. Declare the module and the basis for its stage reading rather than let the census drop the sites.`,
684			);
685		entries.sort(compareEntries);
686		recordedRefusals.sort((left, right) =>
687			left.file === right.file ? left.line - right.line : left.file < right.file ? -1 : 1,
688		);
689		const byOrigin: Record<string, number> = {};
690		const byClassification: Record<string, number> = {};
691		const byStage: Record<string, number> = {};
692		for (const entry of entries) {
693			byOrigin[entry.origin] = (byOrigin[entry.origin] ?? 0) + 1;
694			byClassification[entry.classification] = (byClassification[entry.classification] ?? 0) + 1;
695			byStage[entry.stage] = (byStage[entry.stage] ?? 0) + 1;
696		}
697		const sortedRecord = (record: Record<string, number>): Readonly<Record<string, number>> =>
698			Object.freeze(
699				Object.fromEntries(
700					Object.keys(record)
701						.sort((left, right) => (left < right ? -1 : 1))
702						.map((key) => [key, record[key] as number]),
703				),
704			);
705		return Object.freeze({
706			schemaVersion: REFUSAL_CENSUS_SCHEMA,
707			generatedBy: 'versionless refusal-census',
708			adapterFreezeComposite: ADAPTER_FREEZE_COMPOSITE,
709			roots: Object.freeze(CENSUS_ROOTS.map((scanned) => scanned.root)),
710			filesScanned,
711			summary: Object.freeze({
712				sites: entries.length,
713				byOrigin: sortedRecord(byOrigin),
714				byClassification: sortedRecord(byClassification),
715				byStage: sortedRecord(byStage),
716				distinctCodes: new Set(entries.map((entry) => entry.code)).size,
717				recordedRefusalSites: recordedRefusals.length,
718			}),
719			entries: Object.freeze(entries),
720			recordedRefusals: Object.freeze(recordedRefusals),
721			notEstablished: CENSUS_NOT_ESTABLISHED,
722		});
723	}
724	
725	/** Write the census where the trust surfaces and the fleet report can read it. */
726	export async function writeRefusalCensus(
727		census: RefusalCensus,
728		file = REFUSAL_CENSUS_FILE,
729	): Promise<string> {
730		const target = path.resolve(file);
731		await mkdir(path.dirname(target), { recursive: true });
732		await writeFile(target, `${JSON.stringify(census, null, '\t')}\n`);
733		return file;
734	}
