describe('refusal census — the derivation helpers', () => {
	it('collapses a multi-line guard onto one line without losing a token', () => {
		expect(collapseWhitespace('a\n\t&&\n\tb')).toBe('a && b');
		expect(collapseWhitespace('  ')).toBe('');
